"use client";

import { motion } from "framer-motion";
import Link from "next/link";
import { ArrowRight, Laptop, Megaphone, Cloud, Code2, Database, Search } from "lucide-react";
import { cn } from "@/lib/utils";

const services = [
  {
    id: "web-development",
    title: "Web Development",
    description: "Custom, scalable web applications built with modern technologies like Next.js and TypeScript.",
    icon: Laptop,
    color: "from-blue-500/20 to-cyan-500/20",
    glow: "bg-blue-500/10",
  },
  {
    id: "digital-marketing",
    title: "Digital Marketing",
    description: "Data-driven marketing strategies to boost your online visibility and conversion rates.",
    icon: Megaphone,
    color: "from-purple-500/20 to-pink-500/20",
    glow: "bg-purple-500/10",
  },
  {
    id: "cloud-hosting",
    title: "Cloud Hosting",
    description: "High-performance and secure cloud solutions tailored for your business needs.",
    icon: Cloud,
    color: "from-indigo-500/20 to-blue-500/20",
    glow: "bg-indigo-500/10",
  },
  {
    id: "seo-optimization",
    title: "SEO Optimization",
    description: "Rank higher on Google with data-driven SEO strategies and technical optimization for maximum visibility.",
    icon: Search,
    color: "from-amber-500/20 to-orange-500/20",
    glow: "bg-amber-500/10",
  },
];

export default function ServicesOverview() {
  return (
    <section className="section-padding px-6 md:px-16 relative bg-[#030303] overflow-hidden">
      {/* Background Glow */}
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[1000px] h-[500px] bg-primary/5 blur-[150px] rounded-full pointer-events-none" />

      <div className="max-w-7xl mx-auto relative z-10">
        <div className="text-center mb-16 md:mb-24 px-4">
          <h2 className="h2 mb-6 uppercase">
            Our Premium <span className="text-gradient">Services</span>
          </h2>
          <p className="text-white/40 text-lg md:text-xl max-w-2xl mx-auto mb-8">
            Comprehensive digital solutions engineered for growth and performance.
          </p>
          <div className="w-24 h-1.5 bg-primary mx-auto rounded-full" />
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8 md:gap-10">
          {services.map((service, index) => (
            <motion.div 
              key={service.id}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5, delay: index * 0.1 }}
              viewport={{ once: true }}
              className={cn(
                "group relative p-6 md:p-8 rounded-[2.5rem] bg-white/[0.02] border border-white/5 hover:border-primary/50 transition-all duration-300 hover:-translate-y-1 hover:shadow-2xl hover:shadow-primary/10 overflow-hidden shine-effect"
              )}
            >
              <div className={cn(
                "absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-500",
                service.glow
              )} />

              <div className="relative">
                <div className="relative w-32 h-32 md:w-40 md:h-40 mb-10 md:mb-12 flex items-center justify-center">
                   <div className={cn("absolute inset-0 blur-2xl rounded-full", service.glow)} />
                   <div className="relative w-20 h-20 md:w-24 md:h-24 bg-black/40 backdrop-blur-xl border border-white/10 rounded-[1.5rem] md:rounded-3xl flex items-center justify-center group-hover:scale-110 transition-transform duration-500">
                      <service.icon className="w-8 h-8 md:w-10 md:h-10 text-white" />
                   </div>
                </div>

                <h3 className="h3 mb-4 md:mb-6 uppercase">{service.title}</h3>
                <p className="text-white/40 text-base md:text-lg leading-relaxed mb-8 md:mb-10">{service.description}</p>

                <Link 
                  href={`/services#${service.id}`}
                  className="btn-cta-secondary w-full py-4 rounded-xl md:rounded-2xl font-black text-xs md:text-sm flex items-center justify-center gap-3"
                >
                  Learn More <ArrowRight className="w-4 h-4" />
                </Link>
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
