"use client";

import { motion } from "framer-motion";
import { Globe, ShieldCheck, Zap, Cpu } from "lucide-react";

const clientLogos = [
  { name: "Technoinnovators", icon: Globe, color: "text-blue-500" },
  { name: "FirmX", icon: Zap, color: "text-amber-500" },
  { name: "ElestroPlus", icon: Cpu, color: "text-emerald-500" },
  { name: "Elite Design", icon: Globe, color: "text-purple-500" },
  { name: "Huge Labs", icon: ShieldCheck, color: "text-red-500" },
];

export default function TrustSection() {
  return (
    <section className="py-16 md:py-24 px-6 bg-[#030303] border-t border-white/5 overflow-hidden">
      <div className="max-w-7xl mx-auto">
        <div className="text-center mb-12 md:mb-16">
          <h3 className="h3 text-white/40 uppercase tracking-[0.2em] md:tracking-[0.3em]">
            Trusted <span className="hidden sm:inline">Everywhere</span>
          </h3>
        </div>

        <div className="flex flex-wrap justify-center items-center gap-8 md:gap-16 lg:gap-24 opacity-40 hover:opacity-100 transition-opacity duration-500">
          {clientLogos.map((client) => (
            <motion.div 
              key={client.name}
              whileHover={{ scale: 1.05 }}
              className="flex items-center gap-2 md:gap-3 transition-all cursor-pointer group"
            >
              <client.icon className={`w-6 h-6 md:w-8 md:h-8 ${client.color} transition-all group-hover:drop-shadow-[0_0_10px_rgba(255,255,255,0.2)]`} />
              <span className="text-lg md:text-2xl font-black text-white/80 group-hover:text-white tracking-tighter">
                {client.name}
              </span>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
