"use client";

import { useState } from "react";
import Link from "next/link";
import { Plus, Minus, ArrowRight } from "lucide-react";
import { cn } from "@/lib/utils";

const faqs = [
  {
    question: "What is your development process?",
    answer: "We follow a community-driven development framework that includes Discovery, Strategy, iterative Development (sprints), and rigorous Testing before deployment. Our focus is on scalability and performance from day one.",
  },
  {
    question: "Do you build MVPs for startups?",
    answer: "Yes, SaaS MVP development is one of our core specialties. We help founders validate ideas fast by building production-ready MVPs in 6-10 weeks.",
  },
  {
    question: "Which technologies do you use?",
    answer: "We primarily use Next.js, TypeScript, Tailwind CSS, and GSAP for the frontend. For the backend, we work with Node.js, MongoDB, PostgreSQL, and AWS/Vercel for hosting.",
  },
  {
    question: "How do you handle maintenance?",
    answer: "We offer ongoing support and maintenance packages to keep your application secure, updated, and performing at its peak long after the initial launch.",
  },
];

export default function FAQPreview() {
  const [openIndex, setOpenIndex] = useState<number | null>(0);

  return (
    <section className="section-padding px-6 bg-background relative border-t border-border/40 overflow-hidden">
      <div className="max-w-4xl mx-auto">
        <div className="text-center mb-16 md:mb-20 px-4">
          <h2 className="h2 mb-6 uppercase">
             Common <span className="text-gradient">Questions.</span>
          </h2>
          <p className="text-foreground/60 text-lg md:text-xl max-w-2xl mx-auto">
            Everything you need to know about working with our collective.
          </p>
        </div>

        <div className="space-y-4">
          {faqs.map((faq, index) => (
            <div 
              key={index}
              className={cn(
                "glass rounded-[2rem] md:rounded-3xl overflow-hidden transition-all duration-300 border border-white/5",
                openIndex === index ? "border-primary/30" : "hover:border-white/10"
              )}
            >
              <button 
                onClick={() => setOpenIndex(openIndex === index ? null : index)}
                className="w-full p-6 md:p-8 flex items-center justify-between text-left group"
              >
                <span className={cn(
                  "text-base md:text-xl font-black uppercase tracking-tight transition-colors font-outfit",
                  openIndex === index ? "text-primary" : "text-white/80 group-hover:text-white"
                )}>
                  {faq.question}
                </span>
                <div className={cn(
                  "w-8 h-8 md:w-10 md:h-10 rounded-full flex items-center justify-center transition-all shrink-0",
                  openIndex === index ? "bg-primary text-white" : "bg-white/5 text-white/40"
                )}>
                  {openIndex === index ? <Minus className="w-4 h-4" /> : <Plus className="w-4 h-4" />}
                </div>
              </button>
              
              <div className={cn(
                "overflow-hidden transition-all duration-300",
                openIndex === index ? "max-h-[500px] opacity-100" : "max-h-0 opacity-0"
              )}>
                <div className="p-6 md:p-8 pt-0 border-t border-white/5">
                  <p className="text-foreground/60 leading-relaxed text-sm md:text-base mb-6 md:mb-8">
                    {faq.answer}
                  </p>
                  <Link 
                    href="/faq" 
                    className="inline-flex items-center gap-2 text-primary text-[10px] md:text-xs font-black uppercase tracking-widest hover:gap-3 transition-all"
                  >
                    Details in our FAQ <ArrowRight className="w-4 h-4" />
                  </Link>
                </div>
              </div>
            </div>
          ))}
        </div>

        <div className="mt-12 md:mt-16 text-center">
          <Link 
            href="/contact"
            className="text-white/40 hover:text-white transition-colors text-[10px] md:text-xs font-bold uppercase tracking-widest"
          >
            Still have questions? <span className="text-primary underline underline-offset-8">Talk to an expert</span>
          </Link>
        </div>
      </div>
    </section>
  );
}
